"""Cartesian waypoint controller authored for the frozen PlateSteakMeal scene."""
import numpy as np
import mujoco
from scipy.spatial.transform import Rotation
import casa_tool

class Achieved(Exception):
    pass

class Controller:
    def __init__(self, s):
        self.s=s
        self.m=s.model
        self.k=mujoco.MjData(self.m)
        self.jids=np.array([self.m.joint(f'robot0_joint{i}').id for i in range(1,8)])
        self.qidx=self.m.jnt_qposadr[self.jids]
        self.didx=self.m.jnt_dofadr[self.jids]
        self.limits=self.m.jnt_range[self.jids].copy()
        self.site=s.env.robots[0].eef_site_id['right']
        self.q=s.data.qpos[self.qidx].copy()
        self.grip=-1
        self.stop_success=True
    def pos(self,name=None):
        if name is None:
            return self.s.data.site_xpos[self.site].copy()
        return self.s.data.xpos[self.s.env.obj_body_id[name]].copy()
    def rot(self):
        return self.s.data.site_xmat[self.site].reshape(3,3).copy()
    @staticmethod
    def down(yaw):
        x=np.array([np.cos(yaw),np.sin(yaw),0])
        z=np.array([0,0,-1.])
        return np.column_stack([x,np.cross(z,x),z])
    def ik(self,pos,rot,seed=None):
        self.k.qpos[:]=self.s.data.qpos
        q=self.q.copy() if seed is None else seed.copy()
        jp=np.zeros((3,self.m.nv)); jr=jp.copy()
        for _ in range(120):
            self.k.qpos[self.qidx]=q
            mujoco.mj_kinematics(self.m,self.k)
            mujoco.mj_comPos(self.m,self.k)
            pe=pos-self.k.site_xpos[self.site]
            re=Rotation.from_matrix(rot@self.k.site_xmat[self.site].reshape(3,3).T).as_rotvec()
            err=np.r_[pe,re]
            if np.linalg.norm(pe)<1e-5 and np.linalg.norm(re)<1e-4:
                break
            mujoco.mj_jacSite(self.m,self.k,jp,jr,self.site)
            J=np.vstack([jp[:,self.didx],jr[:,self.didx]])
            dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*1e-5,err)
            dq*=min(1,0.12/max(np.max(np.abs(dq)),1e-10))
            q=np.clip(q+dq,self.limits[:,0]+.001,self.limits[:,1]-.001)
        return q,float(np.linalg.norm(pe)),float(np.linalg.norm(re))
    def step(self,q=None,grip=None,base=None,torso=0,mode=-1):
        if q is not None:self.q=np.asarray(q).copy()
        if grip is not None:self.grip=grip
        a=np.r_[self.q,self.grip,np.zeros(3) if base is None else base,torso,mode]
        r=self.s.step(a)
        if r['success'] and self.stop_success:
            self.s.save_trajectory()
            print('SUCCESS',self.s.check(),flush=True)
            raise Achieved()
        return r
    def move(self,p,R=None,n=None,grip=None,settle=8):
        p=np.array(p,dtype=float)
        p0=self.pos(); R0=self.rot()
        R=R0 if R is None else R
        rv=Rotation.from_matrix(R@R0.T).as_rotvec()
        if n is None:n=max(20,int(np.linalg.norm(p-p0)/.004),int(np.linalg.norm(rv)/.045))
        for i in range(n):
            t=(i+1)/n; t=t*t*(3-2*t)
            pt=p0+(p-p0)*t; Rt=Rotation.from_rotvec(rv*t).as_matrix()@R0
            q,pe,re=self.ik(pt,Rt)
            if pe>.02:print('IK residual',i,round(pe,3),round(re,3),flush=True)
            self.step(q,grip)
        for _ in range(settle):self.step()
        print('MOVE',len(self.s.actions),'eef',self.pos().round(4),'target',p.round(4),flush=True)
    def hold(self,n=15,grip=None):
        for _ in range(n):self.step(grip=grip)
    def status(self):
        from robocasa.utils import object_utils as OU
        print('STATUS',self.s.check(), 'eef',self.pos().round(4),flush=True)
        for name in ['steak','asparagus','random_food','plate','tray']:
            print(name,self.pos(name).round(5),flush=True)
        print('on plate',*[OU.check_obj_in_receptacle(self.s.env,n,'plate') for n in ['steak','asparagus']], 'chili on tray',OU.check_obj_in_receptacle(self.s.env,'random_food','tray'),flush=True)
    def snap(self,name):
        from PIL import Image
        Image.fromarray(self.s.render_grid()).save('/app/output/'+name+'.png')

if __name__=='__main__':
    s=casa_tool.Session('/app/instance.npz')
    c=Controller(s)
